const trackById = id => TRACKS.find(t=>t.id===id);
// Unified lookup: channel catalog first, then public-playlist-only tracks.
function meta(id){
  const t = trackById(id);
  if(t) return {id:t.id, title:t.title, dur:t.dur, cat:CATS[t.cat]||t.cat, views:t.views};
  const p = (typeof PL_META !== 'undefined' && PL_META[id]) || null;
  if(p) return {id, title:p.t, dur:p.d||'3:00', cat:'Playlist cut', views:0};
  return {id, title:id, dur:'3:00', cat:'Track', views:0};
}
function durSecs(str){ const [m, s] = str.split(':').map(Number); return m * 60 + s; }
function fmt(s){ s = Math.max(0, Math.floor(s || 0)); return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`; }

/* ---------- Streaming deck engine (API-free) ---------- */
const embedFrame = document.getElementById('embedFrame');
const deckVideo = document.querySelector('.deck-video');
const deckArtImg = document.getElementById('deckArtImg');
const deckGlyph = document.getElementById('deckGlyph');
const bPlay = document.getElementById('bPlay');
const progress = document.getElementById('progress');
const progressFill = document.getElementById('progressFill');
const progressNether = document.getElementById('progressNether');
const progressNetherFill = document.getElementById('progressNetherFill');
const tCur = document.getElementById('tCur');
const tTot = document.getElementById('tTot');
const upNextTitle = document.getElementById('upNextTitle');
const upNextMeta = document.getElementById('upNextMeta');
const deckArtEl = document.getElementById('deckArt');
const deckGlare = document.querySelector('.deck-glare');
const miniVinylImg = document.getElementById('miniVinylImg');
const reduceMotion = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

/* Auto-framed panels: draw-on borders injected, no HTML churn */
document.querySelectorAll('.framed').forEach(el=>{
  if(getComputedStyle(el).position === 'static') el.style.position = 'relative';
  el.insertAdjacentHTML('beforeend', '<div class="frame-top" aria-hidden="true"></div><div class="frame-bottom" aria-hidden="true"></div>');
});

/* 3D tilt state for the deck art (lerped in tick) */
let tiltTX = 0, tiltTY = 0, tiltX = 0, tiltY = 0;
if(deckArtEl){
  deckArtEl.addEventListener('pointermove', e=>{
    if(reduceMotion) return;
    const r = deckArtEl.getBoundingClientRect();
    tiltTY = ((e.clientX - r.left) / r.width - 0.5) * 14;
    tiltTX = -((e.clientY - r.top) / r.height - 0.5) * 14;
  });
  deckArtEl.addEventListener('pointerleave', ()=>{ tiltTX = 0; tiltTY = 0; });
}
const bArt = document.getElementById('bArt');
const bTitle = document.getElementById('bTitle');
const sArt = document.getElementById('sArt');
const sTitle = document.getElementById('sTitle');

let currentId = 'toDML6Aeh-A';
let mode = 'single';
let qi = 0;
let shuffle = false;
let isPlaying = false;
let offsetSecs = 0;
let startedAt = 0;
let revealed = false;

function embedSrc(id, autoplay, start){
  let src = `https://www.youtube.com/embed/${id}?rel=0`;
  if(autoplay) src += '&autoplay=1';
  if(start > 0) src += `&start=${Math.floor(start)}`;
  return src;
}
function currentDur(){
  const m = meta(currentId);
  const parts = String(m.dur).split(':').map(Number);
  if(parts.length === 2 && parts.every(n=>!isNaN(n))) return parts[0]*60+parts[1];
  return 180;
}
function elapsed(){
  if(!isPlaying) return offsetSecs;
  return Math.min(offsetSecs + (performance.now() - startedAt) / 1000, currentDur());
}
function paintProgress(){
  const d = currentDur() || 1;
  const c = elapsed();
  const pct = (c / d * 100) + '%';
  progressFill.style.width = pct;
  progressNetherFill.style.width = pct;
  progress.setAttribute('aria-valuenow', Math.round(c / d * 100));
  progressNether.setAttribute('aria-valuenow', Math.round(c / d * 100));
  tCur.textContent = fmt(c);
  tTot.textContent = fmt(d);
}
(function tick(){
  if(isPlaying){
    paintProgress();
    if(currentDur() > 0 && elapsed() >= currentDur()){
      advance(1, true);
      toast(`Up next: ${meta(currentId).title} — hit play if it stays paused.`);
    }
  }
  if(!reduceMotion && deckArtEl){
    tiltX += (tiltTX - tiltX) * 0.12;
    tiltY += (tiltTY - tiltY) * 0.12;
    if(Math.abs(tiltX) > 0.01 || Math.abs(tiltY) > 0.01 || deckArtEl.style.transform){
      deckArtEl.style.transform = `perspective(900px) rotateX(${tiltX.toFixed(2)}deg) rotateY(${tiltY.toFixed(2)}deg)`;
      if(deckGlare) deckGlare.style.opacity = Math.min(0.9, (Math.abs(tiltX) + Math.abs(tiltY)) / 14).toFixed(2);
    }
  }
  requestAnimationFrame(tick);
})();
function setPlayingUI(on){
  deckGlyph.textContent = on ? '❚❚' : '▶';
  bPlay.textContent = on ? '❚❚' : '▶';
  document.body.classList.toggle('is-playing', on);
  const sh = document.getElementById('shelf');
  if(sh) sh.classList.toggle('is-playing', on);
}
function startClock(from){
  offsetSecs = Math.max(0, from || 0);
  flushedAt = offsetSecs;
  startedAt = performance.now();
  isPlaying = true;
  setPlayingUI(true);
  paintProgress();
}
function stopClock(keep){
  offsetSecs = keep !== undefined ? keep : elapsed();
  isPlaying = false;
  setPlayingUI(false);
  paintProgress();
}
function playCurrent(from){
  embedFrame.src = embedSrc(currentId, true, from || 0);
  startClock(from || 0);
}
function pauseCurrent(){
  const at = elapsed();
  embedFrame.src = embedSrc(currentId, false, at);
  stopClock(at);
}
function togglePlay(){
  if(isPlaying) pauseCurrent();
  else playCurrent(offsetSecs);
}
bPlay.onclick = togglePlay;
document.getElementById('deckArt').onclick = togglePlay;
document.getElementById('deckArt').onkeydown = e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); togglePlay(); } };
document.getElementById('bVideo').onclick = ()=>{
  revealed = !revealed;
  deckArtImg.classList.toggle('art-hidden', revealed);
  deckVideo.classList.toggle('show-video', revealed);
  document.getElementById('deckArt').classList.toggle('revealed', revealed);
  document.getElementById('bVideo').classList.toggle('on', revealed);
};
// Seek on either bar
let scrubbing = false;
function seekFromBar(barEl, clientX){
  const r = barEl.getBoundingClientRect();
  const frac = Math.min(1, Math.max(0, (clientX - r.left) / r.width));
  const target = frac * currentDur();
  if(isPlaying){ embedFrame.src = embedSrc(currentId, true, target); startClock(target); }
  else stopClock(target);
  paintProgress();
}
function wireSeek(barEl){
  barEl.addEventListener('pointerdown', e=>{ scrubbing = true; barEl.setPointerCapture(e.pointerId); seekFromBar(barEl, e.clientX); });
  barEl.addEventListener('pointermove', e=>{ if(scrubbing) seekFromBar(barEl, e.clientX); });
  barEl.addEventListener('pointerup', ()=>{ scrubbing = false; });
}
wireSeek(progress);
wireSeek(progressNether);
function nudgeSecs(delta){
  const target = Math.min(currentDur(), Math.max(0, elapsed() + delta));
  if(isPlaying){ embedFrame.src = embedSrc(currentId, true, target); startClock(target); }
  else stopClock(target);
  paintProgress();
}
[progress, progressNether].forEach(bar=>bar.addEventListener('keydown', e=>{
  if(e.key === 'ArrowRight') nudgeSecs(5);
  if(e.key === 'ArrowLeft') nudgeSecs(-5);
}));

/* ---------- Track loading + transport ---------- */
let filter = 'all';
function loadIntoDeck(t, autoplay){
  flushListen();
  const m = meta(t.id);
  currentId = t.id;
  deckArtImg.src = `images/tracks/${t.id}.jpg`;
  deckArtImg.alt = `${m.title} artwork`;
  upNextTitle.textContent = m.title;
  upNextMeta.textContent = `${m.cat} • ${m.dur}`;
  bArt.src = `images/tracks/${t.id}.jpg`;
  bTitle.textContent = m.title;
  sArt.src = `images/tracks/${t.id}.jpg`;
  sTitle.textContent = m.title;
  tTot.textContent = m.dur;
  tCur.textContent = '0:00';
  progressFill.style.width = '0%';
  progressNetherFill.style.width = '0%';
  if(autoplay){
    stats.plays++;
    const cat = (trackById(t.id) || {}).cat;
    if(cat){ stats.cats[cat] = (stats.cats[cat] || 0) + 1; }
    store.set('stats', stats);
    pushHistory(t.id);
    playCurrent(0);
  }
  else stopClock(0);
  if(miniVinylImg) miniVinylImg.src = `images/tracks/${t.id}.jpg`;
  if(deckArtEl && !reduceMotion){
    deckArtEl.classList.remove('swap');
    void deckArtEl.offsetWidth;
    deckArtEl.classList.add('swap');
  }
  updateStatsUI();
  updatePlayingState();
}
function updatePlayingState(){
  document.querySelectorAll('.track.playing').forEach(el=>el.classList.remove('playing'));
  document.querySelectorAll('.now-badge').forEach(el=>el.remove());
  const sel = `.track[data-play="${typeof CSS !== 'undefined' && CSS.escape ? CSS.escape(currentId) : currentId}"]`;
  document.querySelectorAll(sel).forEach(el=>{
    el.classList.add('playing');
    const art = el.querySelector('.track__art');
    if(art && !art.querySelector('.now-badge')){
      const b = document.createElement('span');
      b.className = 'now-badge';
      b.textContent = 'PLAYING';
      art.appendChild(b);
    }
  });
}
function playTrack(id, opts={}){
  const m = meta(id);
  const inCatalog = !!trackById(id);
  if(!inCatalog && !(typeof PL_META !== 'undefined' && PL_META[id])) return;
  if(!opts.keepMode) mode = 'single';
  loadIntoDeck({id}, opts.autoplay !== false);
  if(!opts.quiet) openShelf();
}
/* ---------- Now Playing shelf: slides up from the bottom ---------- */
const shelf = document.getElementById('shelf');
const shelfToggle = document.getElementById('shelfToggle');
function openShelf(){
  shelf.classList.add('open');
  shelfToggle.textContent = '▼';
  shelfToggle.setAttribute('aria-label', 'Collapse now playing');
}
function closeShelf(){
  shelf.classList.remove('open');
  shelfToggle.textContent = '▲';
  shelfToggle.setAttribute('aria-label', 'Expand now playing');
}
shelfToggle.onclick = ()=>{ lastActiveAt = Date.now(); shelf.classList.contains('open') ? closeShelf() : openShelf(); placeDancer(); };
document.getElementById('shelfClose').onclick = ()=>{ closeShelf(); placeDancer(); };
document.getElementById('radioLink').onclick = e=>{ e.preventDefault(); openShelf(); placeDancer(); };
function catalogStep(dir, quiet){
  const pool = shuffle ? TRACKS : TRACKS;
  let n;
  if(shuffle && TRACKS.length > 1){
    do { n = TRACKS[Math.floor(Math.random() * TRACKS.length)]; } while(n.id === currentId);
  } else {
    const i = TRACKS.findIndex(t=>t.id===currentId);
    n = TRACKS[(i + dir + TRACKS.length) % TRACKS.length];
  }
  mode = 'single';
  if(quiet) playTrack(n.id, {quiet:true});
  else playTrack(n.id);
}
function advance(dir, auto){
  if(mode === 'queue' && queue.length){
    const ni = qi + dir;
    if(ni >= 0 && ni < queue.length){ qi = ni; playTrack(queue[qi], auto ? {keepMode:true, quiet:true} : {keepMode:true}); return; }
    if(auto){
      if(radio){ radioPlay(); return; }
      toast('Queue finished.'); stopClock(offsetSecs); return;
    }
  } else if(auto && radio){ radioPlay(); return; }
  catalogStep(dir, auto);
}
document.getElementById('bPrev').onclick = prevAction;
document.getElementById('bNext').onclick = ()=>advance(1, false);
document.getElementById('bShuffle').onclick = e=>{
  shuffle = !shuffle;
  document.getElementById('bShuffle').classList.toggle('on', shuffle);
  toast(shuffle ? 'Shuffle on.' : 'Shuffle off.');
};
